from sage.all import *
P=PolynomialRing(QQ,names=['x0','y0','z0','B0','x1','y1','z1','B1','tau','l0','l1','u','v'])
x0,y0,z0,B0,x1,y1,z1,B1,tau,l0,l1,u,v=P.gens()
xs=[x0,x1]; ys=[y0,y1]; zs=[z0,z1]; Bs=[B0,B1]
A=ExteriorAlgebra(P,names=['xp0','c0','bc0','Bp0','xp1','c1','bc1','Bp1'])
aa=A.gens(); xp=[aa[0],aa[4]]; cc=[aa[1],aa[5]]; bc=[aa[2],aa[6]]; bp=[aa[3],aa[7]]
def mon(ids):
    r=A.one()
    for j in ids:r*=aa[j]
    return r
def de(F,x):
    return sum((a.derivative(x)*mon(list(ix)) for ix,a in A(F).monomial_coefficients().items()),A.zero())
def do(F,j):
    out=A.zero()
    for ix,a in A(F).monomial_coefficients().items():
        ids=list(ix)
        if j in ids:
            n=ids.index(j); out+=(-1)**n*a*mon(ids[:n]+ids[n+1:])
    return out
def parity(F):
    pp={len(list(ix))%2 for ix,a in A(F).monomial_coefficients().items() if a!=0}
    assert len(pp)<=1
    return next(iter(pp),0)
def delta(F,w=(1,1)):
    return sum((w[j]*(de(do(F,4*j),xs[j])+de(do(F,4*j+1),ys[j])+de(do(F,4*j+2),zs[j])+de(do(F,4*j+3),Bs[j])) for j in range(2)),A.zero())
def R(F,w=(1,1)):
    return -sum((w[j]*(de(de(F,Bs[j]),xs[j])+do(do(F,4*j+2),4*j+1)) for j in range(2)),A.zero())
S=sum((xp[j]*cc[j]+zs[j]*Bs[j]+xs[j]*Bs[j]-bc[j]*cc[j] for j in range(2)),A.zero())
def bracket(F,G):
    sign=(-1)**parity(F)
    return sign*(delta(F*G)-delta(F)*G-sign*F*delta(G))
def Q(F):
    return sum((cc[j]*de(F,xs[j])+(-xp[j]+bc[j])*de(F,ys[j])-cc[j]*de(F,zs[j])+Bs[j]*do(F,4*j)+Bs[j]*do(F,4*j+2)+(zs[j]+xs[j])*do(F,4*j+3) for j in range(2)),A.zero())
def exR(F,a,w=(1,1)):
    out=A(F); term=A(F)
    for n in range(1,12):
        term=a*R(term,w)/n
        out+=term
        if term==0:return out
    raise ValueError('exponential did not terminate')
def D(F,w=(1,1)):return Q(F)+tau*delta(F,w)
def ev(F):
    zero={g:P.zero() for g in list(P.gens())[:8]}
    return A(sum((a for ix,a in A(F).monomial_coefficients().items() if len(list(ix))==0),P.zero()).subs(zero))
def push(F,w=(1,1)):return ev(exR(F,tau,w))
def hh(F):
    return sum((xs[j]*do(F,4*j+1)+bc[j]*de(F,Bs[j])-ys[j]*do(F,4*j)+bp[j]*de(F,zs[j]) for j in range(2)),A.zero())
def h(F):
    out=A.zero()
    for ix,a in A(F).monomial_coefficients().items():
        ids=list(ix)
        for ex,coef in a.dict().items():
            deg=sum(ex[:8])+len(ids)
            if deg:
                term=P(coef)*prod(P.gen(j)**ex[j] for j in range(P.ngens()))*mon(ids)
                out+=hh(term)/deg
    return out
def hq(F,w=(1,1)):return exR(h(exR(F,tau,w)),-tau,w)
def prodW(F,G,w=(1,1)):return exR(exR(F,tau,w)*exR(G,tau,w),-tau,w)
gens=[A(a) for a in P.gens()[:8]]+list(aa)
tests=[A.one(),A(u),A(u*v)]+gens
