conjugation=all(D(F,w)==exR(Q(exR(F,tau,w)),-tau,w) for F in tests)
d_squared=all(D(D(F,w),w)==0 for F in tests)
stokes=all(push(D(F,w),w)==0 for F in tests)
contract0=all(Q(h(F))+h(Q(F))==F-ev(F) for F in tests)
