def transport(F,a,b):return exR(exR(F,tau,a),-tau,b)
rg=all(D(transport(F,w,w2),w2)==transport(D(F,w),w,w2) for F in tests)
rg_three=all(transport(transport(F,w,w2),w2,w3)==transport(F,w,w3) for F in tests)
rg_push=all(push(transport(F,w,w2),w2)==push(F,w) for F in tests)
