ordinary_not_rg=(transport(A(x0*B0),w,w2)!=transport(A(x0),w,w2)*transport(A(B0),w,w2))
wp_pairs=[(A(x0),A(B0)),(bc[0],cc[0]),(A(x0)*xp[0],bc[1]),(A(u*x0),A(v*B0))]
wick_deriv=all(D(prodW(F,G,w),w)==prodW(D(F,w),G,w)+(-1)**parity(F)*prodW(F,D(G,w),w) for F,G in wp_pairs)
wick_transport=all(transport(prodW(F,G,w),w,w2)==prodW(transport(F,w,w2),transport(G,w,w2),w2) for F,G in wp_pairs)
