moments=all(push(A(x0**a*B0**b))==(A((-tau)**a*factorial(a)) if a==b else A.zero()) for a in range(5) for b in range(5))
ghost_moment=(push(bc[0]*cc[0])==-tau and push(bc[1]*cc[1])==-tau)
# Independent Fourier-pair and Berezin rules on the gauge-fixing Lagrangian.
def actual_gaussian(F):
    out=P.zero()
    for ids,pol in A(F).monomial_coefficients().items():
        ids=list(ids)
        if any(i in ids for i in [0,3,4,7]):continue
        for ex,coef in pol.dict().items():
            if any(ex[i] for i in [1,2,5,6]):continue
            if ex[0]!=ex[3] or ex[4]!=ex[7]:continue
            base=P(coef)*prod(P.gen(j)**ex[j] for j in range(8,P.ngens()))
            base*=(-tau)**ex[0]*factorial(ex[0])*(-tau)**ex[4]*factorial(ex[4])
            for j in range(2):
                part=[i for i in ids if 4*j<=i<4*j+4]
                if part==[4*j+1,4*j+2]:base*=tau
                elif part:base=P.zero()
            out+=base
    return A(out)
integral_matches=all(actual_gaussian(F)==push(F) for F in tests)
# Two blocks really integrate in either order.
def exRblock(F,a,j):
    ww=[0,0];ww[j]=1;return exR(F,a,ww)
fubini=all(ev(exRblock(exRblock(F,tau,0),tau,1))==ev(exRblock(exRblock(F,tau,1),tau,0))==push(F) for F in tests)
physical=(push(A(u*v))==A(u*v) and D(A(u*v))==0 and prodW(A(u),A(v))==A(u*v))
